import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
import { evolvePath } from "@remotion/paths";

// Module-level font loading ensures it's ready before frame 0
const { fontFamily: interFamily } = loadInter();



export type TextAnimationProps = Record<string, any>;

const TextAnimation: React.FC<TextAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 6,
  topText = "$125K a month",
  topTextSize = 81,
  bottomText = "$1.5M a month",
  bottomTextSize = 119,
  topTextColor = "#ffffff",
  bottomTextColor = "#e5f22b",
  lineColor = "#ffffff",
  lineWidth = 6,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout points optimized for 1:1 canvas
  const topTextX = width * 0.40;
  const topTextY = height * 0.25;

  const bottomTextX = width * 0.62;
  const bottomTextY = height * 0.73;

  // Path coordinates designed to create the S-curve connection
  const pathStartX = width * 0.42;
  const pathStartY = height * 0.32;
  const pathEndX = width * 0.62;
  const pathEndY = height * 0.62;

  // S-Curve Bezier Control Points
  const curveOffset = (pathEndY - pathStartY) * 0.55;
  const pathString = `M ${pathStartX} ${pathStartY} C ${pathStartX} ${pathStartY + curveOffset}, ${pathEndX} ${pathEndY - curveOffset}, ${pathEndX} ${pathEndY}`;

  // Animations
  // 1. Top Text fades and slightly scales in
  const topTextSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });
  const topScale = interpolate(topTextSpring, [0, 1], [0.8, 1]);
  const topOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Line draws from top to bottom
  const lineProgress = interpolate(frame, [15, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });
  const evolution = evolvePath(lineProgress, pathString);

  // 3. Bottom Text springs up with a bounce
  const bottomTextSpring = spring({
    frame: frame - 40,
    fps,
    config: { damping: 10, mass: 1.2, stiffness: 100 },
  });
  const bottomScale = interpolate(bottomTextSpring, [0, 1], [0.2, 1]);
  const bottomOpacity = interpolate(frame, [40, 50], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        overflow: "hidden",
      }}
    >
      {/* SVG Layer for the connecting line */}
      <AbsoluteFill>
        <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
          <path
            d={pathString}
            strokeDasharray={evolution.strokeDasharray}
            strokeDashoffset={evolution.strokeDashoffset}
            fill="transparent"
            stroke={lineColor}
            strokeWidth={lineWidth}
            strokeLinecap="round"
            style={{ transition: "none" }}
          />
        </svg>
      </AbsoluteFill>

      {/* Top Text Element */}
      <div
        style={{
          position: "absolute",
          left: topTextX,
          top: topTextY,
          transform: `translate(-50%, -50%) scale(${topScale})`,
          opacity: topOpacity,
          color: topTextColor,
          fontSize: width * (topTextSize / 1080),
          fontWeight: 700,
          whiteSpace: "nowrap",
          letterSpacing: "-0.04em",
          transition: "none",
        }}
      >
        {topText}
      </div>

      {/* Bottom Text Element */}
      <div
        style={{
          position: "absolute",
          left: bottomTextX,
          top: bottomTextY,
          transform: `translate(-50%, -50%) scale(${bottomScale})`,
          opacity: bottomOpacity,
          color: bottomTextColor,
          fontSize: width * (bottomTextSize / 1080),
          fontWeight: 800,
          whiteSpace: "nowrap",
          letterSpacing: "-0.05em",
          transition: "none",
        }}
      >
        {bottomText}
      </div>
    </AbsoluteFill>
  );
};

export default TextAnimation;